SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "罗弘信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：罗弘信。", "biography": null, "status": "draft", "id": "da48e163-21a8-54a2-a3a0-cdef2344d96a"}, {"name": "刘建锋", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：刘建锋。", "biography": null, "status": "draft", "id": "084d26d2-8aae-5f9d-9127-ca3c97b203b6"}, {"name": "陈赡", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：陈赡。", "biography": null, "status": "draft", "id": "b2a286bf-eab7-5969-8eb0-a9f2b325a494"}, {"name": "张佶", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：张佶。", "biography": null, "status": "draft", "id": "3e2c7882-9436-5f5d-8d37-e452a1db7890"}, {"name": "马殷", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁封马殷为楚王”中为受封者。", "biography": null, "status": "draft", "id": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"name": "姚彦章", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：姚彦章。", "biography": null, "status": "draft", "id": "3efed9a0-6cef-5447-bb54-71b79c98d5d0"}, {"name": "李琼", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：李琼。", "biography": null, "status": "draft", "id": "778953c5-1675-5fe6-bcec-c96d85e327be"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "河涨将毁滑州，朱温决分二河为害更甚", "start_year": 896, "end_year": 896, "time_original": "896年夏四月辛酉", "dynasty": "唐", "description": "河水上涨将毁滑州城，朱温命决分为两河，夹滑城向东，灾害更重。", "phases": [], "location_name": "滑州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e61b9094-df69-50f9-8b9b-d704545a816c"}, {"title": "李克用攻洹水杀魏兵万余，进攻魏州", "start_year": 896, "end_year": 896, "time_original": "896年四月条；确日未载", "dynasty": "唐", "description": "李克用攻击罗弘信，攻洹水，杀魏兵万余，继而进攻魏州。", "phases": [], "location_name": "洹水、魏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b8735839-384a-5a2c-8642-6c5f4b8e6581"}, {"title": "刘建锋与陈赡妻私通", "start_year": null, "end_year": null, "time_original": "卷260乾宁三年条背景；起始未载", "dynasty": "唐", "description": "史书记长直兵陈赡妻美，刘建锋与她私通。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "fe9ee206-46a8-5f4a-ab98-68d173710008"}, {"title": "陈赡以铁挝击杀刘建锋", "start_year": 896, "end_year": 896, "time_original": "896年四月条；确日未载", "dynasty": "唐", "description": "陈赡袖藏铁挝，将刘建锋击杀。", "phases": [], "location_name": "武安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c234bc1f-6016-5c6c-a768-c5903f29f09d"}, {"title": "诸将杀陈赡，迎张佶为留后", "start_year": 896, "end_year": 896, "time_original": "896年四月刘建锋被杀后条；确日未载", "dynasty": "唐", "description": "诸将杀陈赡，迎行军司马张佶为留后。", "phases": [], "location_name": "武安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b9783cf0-d51c-5f9c-9e46-f3066144ae4b"}, {"title": "张佶将入府，马踶啮伤左髀", "start_year": 896, "end_year": 896, "time_original": "896年四月迎留后以后；确日未载", "dynasty": "唐", "description": "张佶将入府时，马忽然踢咬，伤其左大腿。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "35872503-bc63-5eb3-b3be-f24ef2b02c22"}, {"title": "张佶荐马殷为主，以牒召之", "start_year": 896, "end_year": 896, "time_original": "896年四月张受伤以后；确日未载", "dynasty": "唐", "description": "马殷尚未攻下邵州。张佶向诸将称马殷勇有谋、宽厚乐善胜于自己，是应立之主，发牒召马殷。", "phases": [], "location_name": "武安、邵州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bbccad15-fd11-5131-a091-0921f43f7801"}, {"title": "姚彦章劝犹豫的马殷赴长沙", "start_year": 896, "end_year": 896, "time_original": "896年四月张召马以后；确日未载", "dynasty": "唐", "description": "马殷犹豫未行，听直军将、汝南人姚彦章称他与刘建锋张佶一体，刘遇祸张受伤，天命人望应归他。", "phases": [], "location_name": "邵州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f708f5d2-42a6-59ac-be35-48c1987d7430"}, {"title": "马殷令李琼留攻邵州，赴长沙", "start_year": 896, "end_year": 896, "time_original": "896年四月姚劝以后；确日未载", "dynasty": "唐", "description": "马殷令亲从都指挥使李琼留攻邵州，自己直接去长沙。", "phases": [], "location_name": "邵州、长沙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "efa356c6-664f-523e-99b1-28c3b16f1730"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

